 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    width = len(out[0])
    background = Counter(v for row in out for v in row).most_common(1)[0][0]
    full_colors = {row[0] for row in out if row and all(v == row[0] for v in row) and row[0] != background}
    for color in full_colors:
        for row in out:
            if color in row and not all(v == color for v in row):
                positions = [i for i, v in enumerate(row) if v == color]
                if positions:
                    lo, hi = min(positions), max(positions)
                    if positions == list(range(lo, hi + 1)) and len(positions) * 2 == width:
                        for i in range(width):
                            if row[i] != color:
                                row[i] = 1
                        return out
    return out
